def extract_emails_state(text):
    emails = []
    seen = set()
    current = []
    for ch in text:
        if ch.isalnum() or ch in "._%+-":
            current.append(ch)
        else:
            candidate = "".join(current)
            if "@" in candidate and "." in candidate.split("@")[-1]:
                if candidate not in seen:
                    seen.add(candidate)
                    emails.append(candidate)
            current = []
    candidate = "".join(current)
    if "@" in candidate and "." in candidate.split("@")[-1]:
        if candidate not in seen:
            seen.add(candidate)
            emails.append(candidate)
    return emails

