def remove_duplicates_set(arr):
    seen = set()
    k = 0
    for x in arr:
        if x not in seen:
            seen.add(x)
            arr[k] = x
            k += 1
    return arr[:k]

def remove_duplicates_inplace(arr):
    k = 0
    for i in range(len(arr)):
        duplicate = False
        for j in range(k):
            if arr[j] == arr[i]:
                duplicate = True
                break
        if not duplicate:
            arr[k] = arr[i]
            k += 1
    return arr[:k]

def is_palindrome(s: str) -> bool:
    left, right = 0, len(s) - 1
    while left < right:
        while left < right and not s[left].isalnum():
            left += 1
        while left < right and not s[right].isalnum():
            right -= 1
        if left < right:
            if s[left].lower() != s[right].lower():
                return False
            left += 1
            right -= 1
    return True

