    total = tiles_length * tiles_width * 1.05
    return int(-(-total // 1))

def calculate_weighted_average(scores, credits):
    total_credits = sum(credits)
    if total_credits == 0:
        return 0.0
    total_score = sum(score * credit for score, credit in zip(scores, credits))
    return total_score / total_credits

def update_weighted_average(old_average, old_total_credits, new_score, new_credit):
    new_total_credits = old_total_credits + new_credit
    if new_total_credits == 0:
        return 0.0, 0.0
    new_average = (old_average * old_total_credits + new_score * new_credit) / new_total_credits
    return new_average, new_total_credits

