def calculate_electricity_fee(peak, valley, base_price):
    total = peak + valley
    peak_fee = peak * base_price * 1.5
    valley_fee = valley * base_price * 0.5
    base_total = peak_fee + valley_fee
    if total > 300:
        additional = (total - 300) * 0.1
    else:
        additional = 0
    return base_total + additional

