def extract_dates_B(text):
    result = []
    seen = set()
    i = 0
    n = len(text)
    while i < n:
        if (i + 10 <= n and text[i:i+4].isdigit() and text[i+4] == '-' and
            text[i+5:i+7].isdigit() and text[i+7] == '-' and text[i+8:i+10].isdigit()):
            date = text[i:i+10]
            if date not in seen:
                seen.add(date)
                result.append(date)
            i += 10
        else:
            i += 1
    return result

